#[derive(Clone)]
pub struct RemoteGatewayManager {
    state: Arc<RemoteGatewayState>,
    server_handle: Arc<Mutex<Option<RemoteServerHandle>>>,
}

impl RemoteGatewayManager {
    pub fn new(state: Arc<RemoteGatewayState>) -> Self {
        Self {
            state,
            server_handle: Arc::new(Mutex::new(None)),
        }
    }

    pub fn state(&self) -> &Arc<RemoteGatewayState> {
        &self.state
    }

    pub async fn restore_persisted_listener(&self) -> Result<bool, String> {
        let mode = self.state.config.read().mode;
        if mode == RemoteNetworkMode::Off {
            return Ok(false);
        }

        if let Some(handle) = self.server_handle.lock().take() {
            handle.stop();
        }

        let (handle, _addr) = start_remote_server(Arc::clone(&self.state))
            .await
            .map_err(|e| format!("Failed to restore remote gateway listener: {e}"))?;
        *self.server_handle.lock() = Some(handle);
        Ok(true)
    }

    pub fn stop(&self) {
        if let Some(handle) = self.server_handle.lock().take() {
            handle.stop();
        }
    }
}

