        validate_safe_ownership_and_type(&socket_path, RuntimeNodeKind::Socket)?;
        fs::set_permissions(&socket_path, fs::Permissions::from_mode(0o600))
            .map_err(|error| format!("Failed to secure daemon socket: {error}"))?;

