    RemoteGatewayConfig, RemoteGatewayState, RemoteNetworkMode, RemoteRestartPolicy,
};
use crate::remote::tailscale::{check_tailscale_status, SystemCommandRunner, TailscaleStatus};
use parking_lot::Mutex;
