use ferryx_lib::daemon::client::DaemonClient;
use ferryx_lib::daemon::server::DaemonServer;
use ferryx_lib::remote::auth::DevicePermission;
use ferryx_lib::remote::protocol::RemoteActiveDesktopSelection;
use ferryx_lib::remote::state::{RemoteGatewayConfig, RemoteNetworkMode};
use std::sync::Arc;
use tempfile::tempdir;
use tokio::net::UnixListener;

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let dir = tempdir()?;
    let socket_path = dir.path().join("daemon.sock");
    let config_path = dir.path().join("remote-config.json");
    let auth_path = dir.path().join("remote-auth.json");

    let listener = UnixListener::bind(&socket_path)?;
    let server = Arc::new(DaemonServer::new_with_paths(
        Some(config_path),
        Some(auth_path),
    ));
    let server_clone = Arc::clone(&server);

    let server_task = tokio::spawn(async move {
        loop {
            match listener.accept().await {
                Ok((stream, _)) => {
                    let s = Arc::clone(&server_clone);
                    tokio::spawn(async move {
                        s.handle_client(stream).await;
                    });
                }
                Err(_) => break,
            }
        }
    });

    let client = DaemonClient::new_with_socket(socket_path);

    // Register temporary workspace
    let repo_dir = dir.path().join("repo");
    std::fs::create_dir_all(&repo_dir)?;
    ferryx_lib::worktree::run_git(&repo_dir, &["init"])
        .map_err(|e| format!("git init failed: {e}"))?;
    ferryx_lib::worktree::run_git(
        &repo_dir,
        &[
            "-c",
            "user.name=QA Tester",
            "-c",
            "user.email=qa@example.com",
            "commit",
            "--allow-empty",
            "-m",
            "initial",
        ],
    )
    .map_err(|e| format!("git commit failed: {e}"))?;

    let ws_id = "ws-qa";
    client
        .register_workspace(ws_id, repo_dir.to_str().unwrap())
        .await
        .map_err(|e| format!("register workspace failed: {e}"))?;

    // Spawn daemon PTY
    let client_req_id = uuid::Uuid::new_v4().to_string();
    let session_id = client
        .spawn_terminal(
            client_req_id,
            ws_id.to_string(),
            None,
            Some(repo_dir.to_str().unwrap().to_string()),
            80,
            24,
        )
        .await
        .map_err(|e| format!("spawn terminal failed: {e}"))?;

    // Mark as active
    client
        .remote_set_active_selection(Some(RemoteActiveDesktopSelection {
            workspace_id: Some(ws_id.to_string()),
            worktree_slug: None,
            worktree_label: Some("main".to_string()),
            session_id: Some(session_id.clone()),
        }))
        .await
        .map_err(|e| format!("set active selection failed: {e}"))?;

    // Determine port from FERRYX_REMOTE_QA_PORT env var (default to 43821)
    let requested_port: u16 = std::env::var("FERRYX_REMOTE_QA_PORT")
        .ok()
        .and_then(|p| p.parse().ok())
        .unwrap_or(43821);

    // Enable remote gateway
    client
        .remote_configure(RemoteGatewayConfig {
            mode: RemoteNetworkMode::LocalNetwork,
            port: requested_port,
            allow_control: true,
        })
        .await
        .map_err(|e| format!("remote configure failed: {e}"))?;

    let status = client
        .remote_get_status()
        .await
        .map_err(|e| format!("get remote status failed: {e}"))?;

    let bound_addr_str = status.bound_address.ok_or("missing bound address")?;
    let bound_addr: std::net::SocketAddr = bound_addr_str.parse()?;
    let actual_port = bound_addr.port();

    // Create & exchange Control pairing code
    let pair_code = client
        .remote_create_pairing_code(Some(DevicePermission::Control))
        .await
        .map_err(|e| format!("create pairing code failed: {e}"))?;

    let pair_url = format!("http://127.0.0.1:{actual_port}/api/v1/pair/exchange");
    let pair_payload = format!(r#"{{"code":"{pair_code}","deviceName":"QA-Curl-Client"}}"#);

    let (pair_status, pair_body) = http_post_simple(&pair_url, &pair_payload).await;
    if pair_status != 200 {
        return Err(format!("Pair exchange failed with status {pair_status}: {pair_body}").into());
    }

    // Print exact READY line required
    println!("READY http://127.0.0.1:{actual_port}/api/v1/health");

    // Wait for Ctrl-C
    tokio::signal::ctrl_c().await?;

    // Clean shutdown
    let _ = client
        .remote_configure(RemoteGatewayConfig {
            mode: RemoteNetworkMode::Off,
            port: actual_port,
            allow_control: true,
        })
        .await;

    let _ = client.close_terminal(&session_id).await;
    server_task.abort();

    println!("STOPPED");
    Ok(())
}

async fn http_post_simple(url: &str, body: &str) -> (u16, String) {
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    let host_port = url
        .trim_start_matches("http://")
        .split('/')
        .next()
        .unwrap();
    let parsed: std::net::SocketAddr = host_port.parse().unwrap();

    let path = format!(
        "/{}",
        url.trim_start_matches("http://")
            .splitn(2, '/')
            .nth(1)
            .unwrap_or("")
    );
    let mut stream = tokio::net::TcpStream::connect(parsed).await.unwrap();
    let req = format!(
        "POST {path} HTTP/1.1\r\nHost: localhost\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",
        body.len()
    );
    stream.write_all(req.as_bytes()).await.unwrap();
    let mut resp_buf = Vec::new();
    stream.read_to_end(&mut resp_buf).await.unwrap();
    let resp_str = String::from_utf8_lossy(&resp_buf);
    let status = resp_str
        .lines()
        .next()
        .and_then(|l| l.split_whitespace().nth(1))
        .and_then(|s| s.parse::<u16>().ok())
        .unwrap_or(0);
    let body_part = resp_str.split("\r\n\r\n").nth(1).unwrap_or("").to_string();
    (status, body_part)
}

